INSERT INTO scc_base_quicksearch_config (QUICKSEARCH_CONFIG_ID, NAME, QUERY_DATASOURCE, QUERY_MODULE, QUERY_LANGUAGE_TYPE, QUERY_MATCH_OPERATOR, QUERY_TABLE, QUERY_MAX_SIZE, QUERY_MODE, CODE_ATTR, VALUE_ATTR, QUERY_LANGUAGE, QUERY_LANGUAGE_CUSTOM, DIALOG_ENABLED, DIALOG_QUERY_TYPE, DIALOG_QUERY_TABLE, DIALOG_QUERY_MAX_SIZE, DIALOG_QUERY_LANGUAGE, DIALOG_QUERY_LANGUAGE_CUSTOM, DESCRIPTION, SELECT_MODE, REFLECT_INPUT_CLASS_NAME, REFLECT_CLASS_NAME, REFLECT_INPUT_METHOD_NAME, REFLECT_METHOD_NAME, REFLECT_INPUT_PROPERTY_NAME, REFLECT_PROPERTY_NAME, SELECT_INPUT_MODE, HTTP_URL, INPUT_HTTP_URL, COMPANY_VIEW_FLAG, CREATED_ID, CREATED_BY, CREATION_DATE, CREATED_BY_IP, CREATED_FULL_NAME, LAST_UPDATED_ID, LAST_UPDATED_BY, LAST_UPDATE_DATE, LAST_UPDATED_BY_IP, LAST_UPDATED_FULL_NAME, TENANT_ID,
                                         VERSION)
VALUES (445679935219712, 'pr_requirement_head', null, 'SUPCOOPERATE_READ', null, 'allMatch', 'scc_pr_requirement_head', 15, null, null, 'REQUIREMENT_HEAD_ID', 'SELECT t.*
FROM (SELECT t.*, CONCAT(ifnull(t.apply_by_nickname,\'\'), \'(\', ifnull(t.APPLY_BY,\'\'), \')\') as APPLY_USER_NAME,
             b.ORG_BU_ID,
             b.ORG_BU_CODE,
             b.ORG_BU_NAME,
             b.REQUIRE_FROM,
             b.PROJECT_NAME,
             b.TOTAL_AMOUNT_BY_TEN_KILO,
             b.INVEST_NO,
             b.NO_REPORT_MONTH_PLAN_REASON,
             b.NEED_PUBLIC
      FROM scc_pr_requirement_head t
               LEFT JOIN scc_npm_pr_require_head b ON t.REQUIREMENT_HEAD_ID = b.REQUIREMENT_HEAD_ID
      WHERE  t.AUDIT_STATUS = \'APPROVED\'
      ORDER BY t.CREATION_DATE DESC) t where 1=1 and t.REQUIREMENT_HEAD_NUM like :query', null, null, null, null, null, 'SELECT t.*
FROM (SELECT t.*, CONCAT(ifnull(t.apply_by_nickname,\'\'), \'(\', ifnull(t.APPLY_BY,\'\'), \')\') as APPLY_USER_NAME,
             b.ORG_BU_ID,
             b.ORG_BU_CODE,
             b.ORG_BU_NAME,
             b.REQUIRE_FROM,
             b.PROJECT_NAME,
             b.TOTAL_AMOUNT_BY_TEN_KILO,
             b.INVEST_NO,
             b.NO_REPORT_MONTH_PLAN_REASON,
             b.NEED_PUBLIC
      FROM scc_pr_requirement_head t
               LEFT JOIN scc_npm_pr_require_head b ON t.REQUIREMENT_HEAD_ID = b.REQUIREMENT_HEAD_ID
      WHERE  t.AUDIT_STATUS = \'APPROVED\'
      ORDER BY t.CREATION_DATE DESC) t where 1=1', null, '', null, '', '', '', '', '', '', null, '', '', 'Y', 8123195817787648, 'super', '2023-10-20 14:33:41', '10.74.159.45', '超级管理员', 8123195817787648, 'super', '2023-11-13 13:52:00', '10.254.103.59', '超级管理员', null, 0);
