VALUES (446411331076096, 'sou_req_head', null, 'SOU_READ', null, 'allMatch', 'scc_npm_sou_req_head', 15, null, null, 'REQ_HEAD_ID', 'select t.* from scc_npm_sou_req_head t where t.STATUS=\'APPROVED\' order by t.CREATION_DATE desc', null, null, null, null, null, 'select t.* from scc_npm_sou_req_head t where t.STATUS=\'APPROVED\' order by t.CREATION_DATE desc', null, '寻源需求列表查询', null, '', '', '', '', '', '', null, '', '', 'N', 8123195817787648, 'super', '2023-10-24 17:45:48', '10.254.103.59', '超级管理员', 8123195817787648, 'super', '2023-11-02 14:41:30', '10.254.103.59', '超级管理员', null, 0);
